package com.mushafi.app;
import android.app.*;
import android.content.*;
import android.os.Build;
import org.json.*;
import java.util.*;

/** Independent completion plan and alarms; never reads or writes the general reading position. */
public final class KhatmaScheduler {
 static final String ACTION="com.mushafi.app.KHATMA_EVENT",PREFS="khatma_plan",CHANNEL="khatma_reminder_v1";
 static final int REQUEST=8120,NOTICE=8121;
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences(PREFS,0);}
 static boolean day(String s){if(s==null||!s.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))return false;try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);return f.format(f.parse(s)).equals(s);}catch(Exception e){return false;}}
 public static JSONObject validate(String text)throws JSONException{if(text==null||text.length()>35000)throw new JSONException("plan size");JSONObject p=new JSONObject(text);if(p.optInt("version")!=1||!p.optString("id").matches("[a-z0-9-]{1,64}")||!day(p.optString("startDay"))||!integer(p,"days",1,604)||!integer(p,"position",1,604)||!Arrays.asList("off","daily","before","after").contains(p.optString("reminder")))throw new JSONException("plan");if(!p.has("dailyPages")||(!p.isNull("dailyPages")&&(!integer(p,"dailyPages",1,604)||p.getInt("days")!=(int)Math.ceil(604.0/p.getInt("dailyPages")))))throw new JSONException("rate");if(p.has("progressPage")&&!integer(p,"progressPage",0,604))throw new JSONException("progress");if(p.has("wardIndex")&&!integer(p,"wardIndex",0,p.getInt("days")-1))throw new JSONException("ward index");JSONObject read=p.getJSONObject("read");if(read.length()>604)throw new JSONException("pages");Iterator<String> it=read.keys();while(it.hasNext()){String key=it.next(),d=read.getString(key);if(!key.matches("[1-9][0-9]{0,2}")||Integer.parseInt(key)>604||!day(d)||d.compareTo(p.getString("startDay"))<0)throw new JSONException("page");}return p;}
 static boolean integer(JSONObject p,String key,int min,int max){Object v=p.opt(key);if(!(v instanceof Number))return false;double d=((Number)v).doubleValue();return d==Math.floor(d)&&d>=min&&d<=max;}
 public static void clear(Context c){prefs(c).edit().clear().commit();schedule(c);}
 public static JSONObject load(Context c){try{return validate(prefs(c).getString("plan",""));}catch(Exception e){return null;}}
 public static JSONObject save(Context c,String text)throws JSONException{JSONObject p=validate(text);if(!prefs(c).edit().putString("plan",p.toString()).commit())throw new JSONException("storage");schedule(c);return new JSONObject().put("ok",true);}
 static class Event{long at;String id;Event(long at,String plan){this.at=at;id=plan+"|"+at;}}
 static List<Event> events(JSONObject p,PrayerSettings s,long now)throws JSONException{List<Event> list=new ArrayList<>();String mode=p.getString("reminder");if(mode.equals("off")||p.getJSONObject("read").length()==604)return list;if(mode.equals("daily")){for(int d=0;d<3;d++){Calendar day=Calendar.getInstance();day.setTimeInMillis(now);day.add(Calendar.DAY_OF_YEAR,d);day.set(Calendar.HOUR_OF_DAY,9);day.set(Calendar.MINUTE,0);day.set(Calendar.SECOND,0);day.set(Calendar.MILLISECOND,0);list.add(new Event(day.getTimeInMillis(),p.getString("id")));}}else if(s.json.optBoolean("confirmed")){for(int d=-1;d<=2;d++){JSONObject times=PrayerCalculator.calculate(s,PrayerCalculator.day(s,now,d));for(String key:PrayerSettings.KEYS){long at=times.getLong(key)+(mode.equals("before")?-5:s.row(key).optInt("iqama")+10)*PrayerCalculator.MINUTE;list.add(new Event(at,p.getString("id")));}}}Collections.sort(list,(a,b)->Long.compare(a.at,b.at));return list;}
 static PendingIntent pending(Context c,Event event){Intent i=new Intent(c,KhatmaAlarmReceiver.class).setAction(ACTION);if(event!=null)i.putExtra("at",event.at).putExtra("id",event.id);return PendingIntent.getBroadcast(c,REQUEST,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static AlarmManager alarm(Context c){return(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);}
 static void channel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,UiLocale.text(c,"تذكير ختمة القرآن"),NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("تذكير مستقل لمتابعة ختمتك من موضعها المحفوظ");((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
 public static synchronized void schedule(Context c){channel(c);android.content.SharedPreferences prefs=prefs(c);long previousAt=prefs.getLong("next",0);String previousId=prefs.getString("nextId","");alarm(c).cancel(pending(c,null));prefs.edit().remove("next").remove("nextId").remove("error").apply();JSONObject p=load(c);if(p==null||p.optString("reminder").equals("off")||p.optJSONObject("read").length()==604){((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(NOTICE);return;}if(!PrayerScheduler.notifications(c)||!PrayerScheduler.channelEnabled(c,CHANNEL)){((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(NOTICE);return;}if(!PrayerScheduler.exact(c))return;try{long now=System.currentTimeMillis();if(!previousId.isEmpty()&&previousAt<=now&&now-previousAt<=120000)deliver(c,new Intent(ACTION).putExtra("at",previousAt).putExtra("id",previousId));Set<String> sent=prefs.getStringSet("sent",Collections.emptySet());for(Event e:events(p,PrayerSettings.load(c),now)){if(e.at<=now||sent.contains(e.id))continue;Intent open=new Intent(c,MainActivity.class).putExtra("openKhatma",true);PendingIntent show=PendingIntent.getActivity(c,8122,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);alarm(c).setAlarmClock(new AlarmManager.AlarmClockInfo(e.at,show),pending(c,e));prefs.edit().putLong("next",e.at).putString("nextId",e.id).apply();break;}}catch(Exception e){prefs.edit().putString("error","تعذر جدولة تذكير الختمة؛ راجع الموقع والصلاحيات").apply();}}
 public static synchronized void deliver(Context c,Intent intent){JSONObject p=load(c);long now=System.currentTimeMillis(),at=intent.getLongExtra("at",0);String id=intent.getStringExtra("id");if(p==null||at>now+2000||now-at>120000||!PrayerScheduler.notifications(c)||!PrayerScheduler.channelEnabled(c,CHANNEL))return;try{boolean valid=false;for(Event e:events(p,PrayerSettings.load(c),now))if(e.id.equals(id)){valid=true;break;}if(!valid)return;Set<String> sent=new HashSet<>(prefs(c).getStringSet("sent",Collections.emptySet()));if(sent.contains(id))return;for(Iterator<String> it=sent.iterator();it.hasNext();){String v=it.next();try{if(now-Long.parseLong(v.substring(v.indexOf('|')+1))>7*86400000L)it.remove();}catch(Exception e){it.remove();}}channel(c);Intent open=new Intent(c,MainActivity.class).putExtra("openKhatma",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,8123,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String body=UiLocale.text(c,"ورد ختمتك ينتظرك · تابع من الصفحة {0} · أنجزت {1} من ٦٠٤ صفحات",UiLocale.number(c,p.getInt("position")),UiLocale.number(c,p.getJSONObject("read").length()));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);AppIdentity.decorate(c,b).setContentTitle(UiLocale.text(c,"موعدك مع القرآن")).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(pi).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).setWhen(at).setColor(AppIdentity.notificationColor(c));if(Build.VERSION.SDK_INT<26)b.setDefaults(Notification.DEFAULT_SOUND);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(NOTICE,b.build());sent.add(id);prefs(c).edit().putStringSet("sent",sent).commit();}catch(Exception ignored){}}
 static String arabic(int n){String s=String.valueOf(n);for(int i=0;i<10;i++)s=s.replace((char)('0'+i),(char)('٠'+i));return s;}
 public static JSONObject status(Context c)throws JSONException{channel(c);JSONObject p=load(c);JSONObject j=new JSONObject().put("notifications",PrayerScheduler.notifications(c)).put("exact",PrayerScheduler.exact(c)).put("next",prefs(c).getLong("next",0)).put("error",prefs(c).getString("error",""));if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getNotificationChannel(CHANNEL);j.put("channel",ch!=null&&ch.getImportance()!=NotificationManager.IMPORTANCE_NONE);}if(p!=null)j.put("plan",p);return j;}
}
